use super::*;
#[test]
fn original_field_header_exchanges_keep_displaced_allocation_and_presence(){let mut target="original long string payload".to_owned();let original=target.as_ptr();let mut setter=Some("authored replacement".to_owned());exchange(&mut setter,&mut target);assert_eq!(target,"authored replacement");assert_eq!(setter.as_ref().unwrap().as_ptr(),original);let mut missing:Option<String>=None;let target_pointer=target.as_ptr();exchange(&mut missing,&mut target);assert_eq!(target.as_ptr(),target_pointer);let mut value=Some([f32::from_bits(0x80000000),0.0,0.0,0.5]);let mut clear=Some(None);exchange(&mut clear,&mut value);assert_eq!(value,None);assert_eq!(clear.unwrap().unwrap()[0].to_bits(),0x80000000);}
#[test]
fn every_typed_sparse_setter_quotes_finite_original_header_work(){assert_eq!(<ParagraphStylePatch as OwnedPatch<ParagraphStyle>>::FIELD_COUNT,7);assert_eq!(<CharacterStylePatch as OwnedPatch<CharacterStyle>>::FIELD_COUNT,7);assert_eq!(<PagePatch as OwnedPatch<Page>>::FIELD_COUNT,12);assert_eq!(<FramePatch as OwnedPatch<Frame>>::FIELD_COUNT,18);for field in 0..18{let patch=FramePatch::default();assert!(patch.field_demand(field).unwrap().copy_bytes>0)}let mut empty=String::with_capacity(4096);empty.clear();let patch=ImageLinkPatch{color_profile:Some(Some(empty)),..Default::default()};assert_eq!(patch.field_demand(4).unwrap().release_bytes,0);let mut authored=patch.color_profile;let mut current=Some("old profile".to_owned());let original=current.as_ref().unwrap().as_ptr();let next=authored.as_ref().unwrap().as_ref().unwrap().as_ptr();exchange(&mut authored,&mut current);assert_eq!(current.as_deref(),Some(""));assert_eq!(current.as_ref().unwrap().as_ptr(),next);assert_eq!(authored.as_ref().unwrap().as_ref().unwrap().as_ptr(),original);}
